import { observable, action, toJS, computed, makeObservable } from 'mobx';
import ajax from '@/utils/ajax';
import { Message } from '@arco-design/web-react';
import language from "@/store/language";
import React from 'react';
import { SchemaPageInstance } from '@/components/schema';


class Store {
    @observable type: string = "";

    pageRef = React.createRef<SchemaPageInstance>();

    @action setType = (key: string) => {
        this.type = key;
        this.setList([]);
    }

    constructor() {
        makeObservable(this);
    }

    @computed get title(){
        return this.type == 'add'? "新增多语言" : "更新多语言";
    }

    @observable selectedRowKeys = [];
    @action setSelectedRowKeys = (keys) => {
        this.selectedRowKeys = keys;
    }


    @observable list = [];

    @action setList = (list) => {
        this.list = list;
    }


    onUpdateList = () => {
        const map = new Map(this.pageRef.current.getTableData().map((o) => [o.id, { ...o, key: o.id }]));
        const updateList = this.selectedRowKeys.map((key) => map.get(key));
        this.setType('edit');
        this.setList(updateList);
    }

    @action changeValue = (index, key, value) => {
        const result = [...this.list];
        result[index][key] = value;
        this.list = result;
    }


    @action deleteIndex = (index: number) => {
        this.list = this.list.filter((_, i) => i != index);
    }


    /**
     * 提交检测
     */
    validateList = async () => {
        const result = toJS(this.list);
        if(!result.length) {
            Message.warning("请输入需要翻译的多语言中文");
            return Promise.reject();
        }
        const zhCNs = result.map((o) => o.zhCN?.trim());
        if(!zhCNs.every((val) => Boolean(val))){
            Message.warning("请检查列表，中文不能为空");
            return Promise.reject();
        }
        if(zhCNs.length > Array.from(new Set(zhCNs)).length){
            Message.warning("当前多语言中文有重复数据，请检查调整数据");
            return Promise.reject();
        }
        if(this.type == 'add'){
            // 多语言检测（存在中文不允许添加）
            const list = await ajax.post('/apijson/gets', {
                'LanguageAll[]': {
                    LanguageAll: {
                        'zhCN{}': zhCNs,
                        "@column": "languekey, id, zhCN"
                    }
                }
            }).then((res) => res.LanguageAll);
            if(list.length){
                Message.error(`当前翻译【${list.map((o) => o.zhCN).join(',')}】已经重复，无法重复添加`);
                return Promise.reject();
            }
        }
        return result;
    }


    /**
     * 多语言提交
     */
    submit = async () => {
        const result = await this.validateList();
        const langKeys = result.map((o) => o.languekey?.trim());
        if(!langKeys.every((val) => Boolean(val))){
            Message.warning("请检查列表，多语言Key不能为空");
            return Promise.reject();
        }
        const list = result.map((o) => ({
            id: o.id,
            languekey: o.languekey.trim(),
            ...language.options.reduce((objs, item) => {
                const key = item.value.replace('-', '');
                return {
                    ...objs,
                    [key]: o[key]?.trim()
                }
            }, {})
        }))
        if(this.type == 'add'){
            return ajax.post('/apijson/post', {
                'LanguageAll[]': list
            }).then((res) => {
                Message.success("多语言新增成功")
                this.setType('')
                this.pageRef.current.reload();
            })
        }else {
            return ajax.post('/apijson/put', {
                'LanguageAll[]': list
            }).then((res) => {
                Message.success("多语言更新成功");
                this.setType('');
                this.pageRef.current.reload();
            })
        }
    }

    /**
     * AI 补全
     */
    changeAiCompletion = async () => {
        const result = await this.validateList();
        const zhCNs = result.map((o) => JSON.stringify(o.zhCN.trim()))
        return ajax.post('https://api.b3n.fun/v1/chat/completions', {
            "model": "gpt-4o-mini",
            "max_tokens": 4096,
            "messages": [
              {
                "role": "user",
                "content": `[${zhCNs.join(',')}], 根据我上面数组中给的中文，生成以下对应的多语言Key（key 生成规则采用英文语意，只能使用小写字母，不要使用_使用.连接，例如a.b.c 这种） 和以下多语言翻译'zh-CN' | 'zh-TW' | 'zh-HK' | 'en-US' | 'de-DE' | 'fr-FR' | 'ru-RU' | 'ja-JP' | 'ko-KR' 。要返回给我字符串json 类型数据，数据格式例如 '[{ key: 'wjfajf', zhCN: '确认' }]'`
              }
            ]
        }, {
            headers: {
                Authorization: 'sk-LULdYg0W1qqLyXBh2934Ae8cF14d4801A42c42331d233aB1'
            }
        }).then((res) => {
            try {
                const { choices } = res;
                const { message } = choices[0];
                const { content } = message;
                const jsonStr = content.slice(content.indexOf('['), content.lastIndexOf(']') + 1);
                const list = JSON.parse(jsonStr.replace(/(\n)/g,''));
                const objs = list.reduce((objs, item) => {
                    return {
                        [item.zhCN]: item,
                        ...objs,
                    }
                }, {})
                this.setList(
                    result.map((o) => {
                        const item = objs[o.zhCN];
                        if(item){
                            const { key, ...langs } = item;
                            let languekey = key.replace('_', '.');
                            if(languekey.indexOf('.') == -1){
                                languekey = `sys.${languekey}`
                            }
                            // 合并AI提供的翻译信息
                            return {
                                ...o,
                                languekey,
                                ...langs,
                            }
                        }
                        return o
                    })
                )
            }catch(e) {
                Message.error("AI 生成失败，请稍后再试～")
            }
        });
    }
}


export default Store;