import React, { useMemo, useState } from "react";
import language from "@/store/language";
import { Button, Card, Modal, Table, TableProps, Input, TableColumnProps, Space } from "@arco-design/web-react";
import { JSONSchemaCustom, SchemaApiJsonPage, SchemaQueryForm, SchemaTable } from "@/components/schema";
import Store from './store';
import { useObserver } from "mobx-react-lite";
import utils from "utils";
import { IconDelete, IconPlus } from "@arco-design/web-react/icon";
import { AsyncButton } from "@/components/custom";

const Index = () => {
    const languageOptions = language.options;
    
    const schema = useMemo(() => {
        

        return {
            type: "object",
            properties: {
                "languekey": {
                    "title": "多语言Key",
                    columnProps: {
                        width: 160,
                        fixed: "left",
                        ellipsis: true,
                    }
                },
                ...languageOptions.reduce((objs, item) => {
                    return {
                        ...objs,
                        [item.value.replace('-', '')]: {
                            title: item.label,
                            columnProps: {
                                ellipsis: true,
                                width: 150,
                            }
                        }
                    }
                },{}),
                updatedAt: {
                    title: "更新时间",
                    columnProps: {
                        width: 180,
                    }
                }
            }
        } as JSONSchemaCustom;
    },[])


    const [store] = useState(() => {
        return new Store();
    })
    

    return useObserver(() => {


        const columns = useMemo(() => {

            return [
                {
                    title: "多语言Key",
                    dataIndex: "languekey",
                    bodyCellStyle: {
                        padding: 2,
                    },
                    fixed: "left",
                    width: 180,
                    render: store.type == 'edit'? undefined : (col, item, index) => {
                        return (
                            <Input
                                value={col}
                                onChange={(val) => {
                                    store.changeValue(index, 'languekey', val);
                                }}
                            />
                        )
                    }
                },
                ...languageOptions.map((o) => {
                    const field = o.value.replace('-', '')
                    return {
                        title: o.label,
                        dataIndex: field,
                        width: 180,
                        fixed: o.value == 'zh-CN'? "left" : undefined,
                        bodyCellStyle: {
                            padding: 2,
                        },
                        render: (col, item, index) => {
                            return (
                                <Input
                                    value={col}
                                    onChange={(val) => {
                                        store.changeValue(index, field, val);
                                    }}
                                />
                            )
                        }
                    } as TableColumnProps;
                }),
                {
                    title: "设置",
                    fixed: "right",
                    width: 100,
                    render: (col, item, index) => {
                        return (
                            <Button
                                onClick={() => {
                                    store.deleteIndex(index)
                                }}
                                icon={
                                    <IconDelete />
                                }
                            ></Button>
                        )
                    }
                }
            ] as TableProps['columns']
        },[store.type])
        

        const { selectedRowKeys, setSelectedRowKeys } = store;


        return (
            <React.Fragment>
                <SchemaApiJsonPage
                    ref={store.pageRef}
                    apijson={{
                        tableName: "LanguageAll",
                        uniqueKey: "id",
                        notAdd: true,
                        findParams: {
                            "@order": "updatedAt-"
                        }
                    }}
                    schemaTable={{
                        rowKey: "id",
                        rowSelection: {
                            selectedRowKeys: selectedRowKeys,
                            onChange: (keys) => {
                                setSelectedRowKeys(keys);
                            }
                        },
                        toolBarRender: [
                            <Button
                                type="primary"
                                onClick={() => {
                                    store.setType('add')
                                }}
                            >
                                新增多语言
                            </Button>,
                            <Button type="primary" disabled={!selectedRowKeys.length} 
                                onClick={() => {
                                    store.onUpdateList();
                                }}
                            >
                                更新多语言
                            </Button>
                        ]
                    }}
                    schema={schema}
                    queryFilterKeys={['languekey', 'zhCN', 'enUS']}
                />
                <Modal
                    title={store.title}
                    style={{
                        width: 1200
                    }}
                    visible={Boolean(store.type)}
                    onCancel={() => {
                        store.setType('');
                    }}
                    onOk={() => {
                        store.submit();
                    }}
                >
                    <div className="flex justify-end">
                        <Space className="mb-4">
                            {store.type == 'add'? (
                                <Button icon={<IconPlus />}
                                    onClick={() => {
                                        store.setList([
                                            ...store.list,
                                            { key: utils.getUuid() },
                                        ])
                                    }}
                                >
                                    新增
                                </Button>
                            ): null}
                            <AsyncButton type="primary"
                                onClick={() => {
                                    return store.changeAiCompletion();
                                }}
                            >
                                AI补全
                            </AsyncButton>
                        </Space>
                    </div>
                    <Table
                        rowKey={"key"}
                        pagination={false}
                        scroll={{
                            x: true,
                            y: true,
                        }}
                        columns={columns}
                        data={store.list}
                    />
                </Modal>
            </React.Fragment>
        )
    })
}


export default Index;